"""Ansible inventory, derived from the manifest and Terraform output on every run.

Reads host variables from service.yml.
"""

from __future__ import annotations

import re
from pathlib import Path
from typing import Any

from .. import paths
from ..errors import PvcError
from ..models import ResolvedService, SiteConfig
from ..roles import BASE_ROLE, KNOWN_ROLES
from ..utils import dump_yaml

HEADER = (
    "# Generated by pvc from service.yml and Terraform output. Do not edit:\n"
    "# the next run overwrites this file. Put host variables under `vars` in service.yml.\n"
)


def group_name(*parts: str) -> str:
    """Ansible-safe group name: svc_<service>, svc_<service>_<host>, role_<role>."""
    return re.sub(r"[^A-Za-z0-9_]", "_", "_".join(parts))


def service_group(service_name: str) -> str:
    return group_name("svc", service_name)


def host_group(service_name: str, host_key: str) -> str:
    return group_name("svc", service_name, host_key)


def build_inventory(
    site: SiteConfig,
    service: ResolvedService,
    terraform_hosts: dict[str, dict[str, Any]],
    private_key: Path,
) -> dict[str, Any]:
    hosts: dict[str, Any] = {}
    children: dict[str, Any] = {
        service_group(service.name): {"hosts": {}},
        group_name("role", BASE_ROLE): {"hosts": {}},
        **{group_name("role", role): {"hosts": {}} for role in KNOWN_ROLES},
    }

    for key, host in service.hosts.items():
        deployed = terraform_hosts.get(key)
        address = (deployed or {}).get("ip") or host.address
        if not address:
            raise PvcError(
                f"No IP address for host '{key}' ({host.name}). The guest agent has not reported one yet; "
                "wait a moment and rerun, or give the host a static ip in service.yml."
            )

        hosts[host.name] = {
            "ansible_host": address,
            "host_key": key,
            "sys_hostname": host.name,
            "vm_id": host.vm_id,
            "proxmox_node": host.node,
            **host.vars,
        }

        children[service_group(service.name)]["hosts"][host.name] = {}
        children[host_group(service.name, key)] = {"hosts": {host.name: {}}}
        children[group_name("role", BASE_ROLE)]["hosts"][host.name] = {}
        for role in host.roles:
            children[group_name("role", role)]["hosts"][host.name] = {}

    return {
        "all": {
            "vars": {
                **site.merged_ansible_vars(),
                "service_name": service.name,
                "service_dir": str(service.directory),
                "user_devops": site.ssh.user,
                "ssh_port": site.ssh.port,
                "ansible_user": site.ssh.user,
                "ansible_port": site.ssh.port,
                "ansible_ssh_private_key_file": str(private_key),
                "ansible_become_password": "{{ vault_devops_password }}",
                "docker_users": [site.ssh.user],
            },
            "hosts": hosts,
            "children": children,
        }
    }


def inventory_path(service_name: str) -> Path:
    return paths.service_state_dir(service_name) / "inventory.yml"


def write_inventory(inventory: dict[str, Any], service_name: str) -> Path:
    path = inventory_path(service_name)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(dump_yaml(inventory, header=HEADER))
    return path
